    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

  /* Provide restrict-qualified views for better vectorization/alias analysis. */
  DATA_TYPE (*restrict Cr)[NJ] = (DATA_TYPE (*restrict)[NJ])C;
  DATA_TYPE (*restrict Ar)[NK] = (DATA_TYPE (*restrict)[NK])A;
  DATA_TYPE (*restrict Br)[NJ] = (DATA_TYPE (*restrict)[NJ])B;

  const int NI_ = _PB_NI;
  const int NJ_ = _PB_NJ;
  const int NK_ = _PB_NK;

  /* Tunable tile sizes (safe defaults; adjust per CPU). */
#ifndef GEMM_TILE_J
#define GEMM_TILE_J 128
#endif
#ifndef GEMM_TILE_K
#define GEMM_TILE_K 64
#endif

#pragma scop
  /* Parallelize across i (rows of C): no races since each thread owns distinct rows. */
#pragma omp parallel for schedule(static) private(j,k)
  for (i = 0; i < NI_; i++) {

    /* Scale C row by beta (vectorizable). */
#pragma omp simd
    for (j = 0; j < NJ_; j++) {
      Cr[i][j] = Cr[i][j] * beta;
    }

    /* Blocked j/k loops for cache locality; keep accumulation order identical within a row. */
    for (int kk = 0; kk < NK_; kk += GEMM_TILE_K) {
      const int kend = (kk + GEMM_TILE_K < NK_) ? (kk + GEMM_TILE_K) : NK_;

      for (int jj = 0; jj < NJ_; jj += GEMM_TILE_J) {
        const int jend = (jj + GEMM_TILE_J < NJ_) ? (jj + GEMM_TILE_J) : NJ_;

        for (k = kk; k < kend; k++) {
          const DATA_TYPE a_ik = alpha * Ar[i][k];

          /* Vectorize over j: contiguous access for both B row and C row. */
#pragma omp simd
          for (j = jj; j < jend; j++) {
            Cr[i][j] += a_ik * Br[k][j];
          }
        }
      }
    }
  }
#pragma endscop
}

int main(int argc, char** argv)
{
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

