		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = (DATA_TYPE)i;
      u2[i] = ((DATA_TYPE)(i+1) / fn) / (DATA_TYPE)2.0;
      v1[i] = ((DATA_TYPE)(i+1) / fn) / (DATA_TYPE)4.0;
      v2[i] = ((DATA_TYPE)(i+1) / fn) / (DATA_TYPE)6.0;
      y[i]  = ((DATA_TYPE)(i+1) / fn) / (DATA_TYPE)8.0;
      z[i]  = ((DATA_TYPE)(i+1) / fn) / (DATA_TYPE)9.0;
      x[i] = (DATA_TYPE)0.0;
      w[i] = (DATA_TYPE)0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / (DATA_TYPE)n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  /* Use local restrict-qualified aliases to help vectorization.
     This does not change signatures and preserves semantics. */
  DATA_TYPE (*restrict Ar)[N] = (DATA_TYPE (*restrict)[N])A;
  DATA_TYPE *restrict ru1 = u1;
  DATA_TYPE *restrict rv1 = v1;
  DATA_TYPE *restrict ru2 = u2;
  DATA_TYPE *restrict rv2 = v2;
  DATA_TYPE *restrict rw  = w;
  DATA_TYPE *restrict rx  = x;
  DATA_TYPE *restrict ry  = y;
  DATA_TYPE *restrict rz  = z;

  const int Nloc = _PB_N;

  /* Fuse z addition into x computation later by starting accum from z[i]
     is safe since x is not used before that point except being updated. */

  /* A = A + u1*v1^T + u2*v2^T */
#pragma omp parallel for schedule(OMP_SCHEDULE) private(j)
  for (i = 0; i < Nloc; i++) {
    const DATA_TYPE u1i = ru1[i];
    const DATA_TYPE u2i = ru2[i];
    DATA_TYPE *restrict Ai = Ar[i];
#pragma omp simd
    for (j = 0; j < Nloc; j++) {
      Ai[j] = Ai[j] + u1i * rv1[j] + u2i * rv2[j];
    }
  }

