  for (i = 0; i < Nloc; i++) {
    DATA_TYPE acc = (DATA_TYPE)0.0;
#pragma omp simd reduction(+:acc)
    for (j = 0; j < Nloc; j++) {
      acc += Ar[j][i] * ry[j];
    }
    rx[i] = rx[i] + beta * acc + rz[i];
  }

  /* w[i] = w[i] + alpha * sum_j A[i][j] * x[j] */
#pragma omp parallel for schedule(OMP_SCHEDULE) private(j)
  for (i = 0; i < Nloc; i++) {
    const DATA_TYPE *restrict Ai = Ar[i];
    DATA_TYPE acc = (DATA_TYPE)0.0;
