		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Two main improvements:
     1) Parallelize over i (each thread owns one row i and its j<=i entries) => no races.
     2) Use cache blocking over k and j, and hoist A[i][k] out of j-loop.
        Also scale C[i][j] by beta once before accumulation.
