    const int BJ = 64;

    for (int kk = 0; kk < _PB_M; kk += BK) {
      int kend = MIN(_PB_M, kk + BK);

      for (int jj = 0; jj <= i; jj += BJ) {
        int jend = MIN(i + 1, jj + BJ);

        for (k = kk; k < kend; k++) {
