	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite. */
  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Parallel zero-fill of B */
#pragma omp parallel for schedule(static) private(s)
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      (POLYBENCH_ARRAY(B))[r][s] = 0;

  /* Compute B = A * A^T with t outermost to preserve exact FP order per (r,s).
     Parallelize over r (each thread updates distinct B[r][*] row => no races). */
  for (t = 0; t < n; ++t) {
