      for (s = 0; s < n; ++s) {
        Br[s] += art * A[s][t];
      }
    }
  }

  /* Copy back A = B (parallel, no races) */
#pragma omp parallel for schedule(static) private(s)
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

